  if (method === "mailto") {
    const subject = `Your Visit QR Pass — SAAD Enterprise`;
    const body = [
      `Dear ${visitorName},`,
      ``,
      `Your visit to SAAD Enterprise has been approved.`,
      ``,
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
      `  VISIT PASS DETAILS`,
