      `  QR Code   : ${r.qrCode}`,
      `  Host      : ${hostName}`,
      `  Date      : ${r.visitDate}`,
      `  Purpose   : ${r.purpose || "Visit"}`,
      `  Status    : APPROVED ✓`,
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
      ``,
      `📱 YOUR QR PASS IMAGE:`,
      `${qrImageUrl}`,
