              <div style={{ fontSize: 13, color: "var(--ink3)" }}>Print the pass — visitor shows the paper QR at gate. Guard scans from paper.</div>
            </div>
          </div>
        </Modal>
      )}

      {noMobModal && <NoMobileOptions request={noMobModal} onClose={() => setNoMobModal(null)} />}
    </div>
  );
};

